insert into logos_academy.activity_requirements(
  id, tenant_id, activity_template_id, kind, label, is_required, position, project_slot, deleted_at, updated_at
)
select
  md5('logos-academy-explorer-v3-requirement-' || d.activity || '-' || d.position)::uuid,
  t.id,
  md5('logos-academy-explorer-v3-activity-' || d.activity)::uuid,
  d.kind,
  d.label,
  d.required,
  d.position,
  d.slot,
  null,
  now()
from tenant t cross join data d
on conflict (id) do update set
  kind = excluded.kind,
  label = excluded.label,
  is_required = excluded.is_required,
  position = excluded.position,
  project_slot = excluded.project_slot,
  deleted_at = null,
  updated_at = now();

update logos_academy.activity_criteria
set deleted_at = now(), updated_at = now()
where activity_template_id in (
  select md5('logos-academy-explorer-v3-activity-' || n)::uuid
  from generate_series(1, 16) n
);

with tenant as (
  select id from logos_academy.tenants where slug = 'logos-academy' and deleted_at is null
), data(activity, position, label, description) as (values
  (1,1,'Problema específico','Público, necessidade e promessa são concretos e diferentes de um chat genérico.'),(1,2,'Contrato completo','Há três modos ou especialidades, instrução complementar e limites explícitos.'),(1,3,'Interface utilizável','O fluxo é responsivo e comunica estados vazio e carregando.'),(1,4,'Autoria explicada','As escolhas visuais e de interação são justificadas; elemento reativo é opcional.'),
  (2,1,'Segredo protegido','A chave não aparece em cliente, arquivo enviado, repositório ou log.'),(2,2,'Entrada validada','A rota rejeita entrada ausente, excessiva ou em formato incorreto.'),(2,3,'Modos realmente distintos','Cada seleção altera instrução e comportamento sem quebrar regras permanentes.'),(2,4,'Saída previsível','O contrato estruturado é validável e renderizável pela interface.'),
  (3,1,'Contexto controlado','O histórico é persistido sem enviar conversa ilimitada ao modelo.'),(3,2,'Falha recuperável','Fallback, erro e nova tentativa possuem comportamento verificável.'),(3,3,'Uso limitado','Rate limit ocorre no servidor e informa o usuário com clareza.'),(3,4,'Visual seguro','A aplicação renderiza uma estrutura validada e não injeta SVG arbitrário.'),
  (4,1,'Fluxo completo','Interface, modos, IA, memória e proteções funcionam no deploy.'),(4,2,'Cinco testes relevantes','A matriz cobre sucesso, regra proibida, modo, fallback e limite ou contexto.'),(4,3,'Melhoria comprovada','Ao menos uma falha encontrada foi corrigida e comparada.'),(4,4,'Projeto explicável','README, arquitetura, limites e demonstração permitem compreender a solução.'),
  (5,1,'Brief acionável','Objetivo, público, mensagem, tom, canais, restrições e CTA orientam a criação.'),(5,2,'Direções distintas','As três opções diferem em conceito, composição e linguagem, não apenas em cor.'),(5,3,'Referências analisadas','Cada referência registra o princípio aproveitado sem propor cópia.'),(5,4,'Escolha justificada','A matriz compara critérios e explica a direção selecionada.'),
  (6,1,'Sistema consistente','Tokens e componentes sustentam reconhecimento entre as peças.'),(6,2,'Curadoria documentada','Prompts, descartes e motivo das escolhas estão registrados.'),(6,3,'Adaptação real','Os formatos mudam hierarquia e composição conforme o canal.'),(6,4,'Copy coerente','Texto, tom e chamada para ação seguem brief e espaço disponível.'),
  (7,1,'Narrativa clara','Landing e vídeo conduzem da promessa ao CTA sem contradição.'),(7,2,'Responsividade','O fluxo principal funciona em 375, 768 e 1440 px.'),(7,3,'Movimento com função','Animação orienta atenção e respeita preferência por redução.'),(7,4,'Audiovisual completo','Vídeo ou storyboard define gancho, cenas, ritmo, texto ou áudio e encerramento.'),
  (8,1,'Coerência do sistema','Brief, identidade, peças, página e audiovisual comunicam a mesma ideia.'),(8,2,'Revisão externa','Outra pessoa descreveu a mensagem e sua leitura foi registrada.'),(8,3,'Correção priorizada','A incoerência de maior impacto foi corrigida antes da publicação.'),(8,4,'Case explicável','A entrega mostra processo, decisões, descartes, resultado e próximos passos.'),
  (9,1,'Problema observável','O processo atual apresenta frequência, esforço, erro ou risco identificável.'),(9,2,'Fluxos compreensíveis','Diagramas mostram atores, entrada, decisões, saídas e exceções.'),(9,3,'Contrato validável','Campos, tipos, obrigatoriedade, estados e consentimento estão definidos.'),(9,4,'Limite humano','Casos que exigem revisão estão separados das decisões automáticas.'),
  (10,1,'Entrada confiável','Dados inválidos são recusados ou encaminhados antes do processamento.'),(10,2,'Estado persistido','Cada execução mantém identificador e estado rastreável.'),(10,3,'Regra explícita','Decisões previsíveis usam regra determinística compreensível.'),(10,4,'Saída útil','O caminho feliz gera consequência real e verificável.'),
  (11,1,'IA delimitada','A tarefa possui prompt, esquema, validação e confiança ou justificativa.'),(11,2,'Revisão segura','Baixa confiança e casos sensíveis não avançam automaticamente.'),(11,3,'Sem duplicidade','Repetir o mesmo evento não produz uma segunda consequência.'),(11,4,'Falha observável','Retry é limitado e logs explicam o estado sem expor informação sensível.'),
  (12,1,'Cenários completos','Sucesso, inválido, incerteza, duplicidade e falha externa foram executados.'),(12,2,'Estados coerentes','Cada cenário termina em estado, saída e log compatíveis.'),(12,3,'Risco corrigido','A falha de maior impacto recebeu correção demonstrável.'),(12,4,'Operação explicável','Diagrama, export e painel ou relatório permitem acompanhar o fluxo.'),
  (13,1,'Problema sustentado','Há evidência ou observação concreta de uma necessidade de usuário.'),(13,2,'Hipótese mensurável','Promessa, hipótese e métrica permitem avaliar valor.'),(13,3,'Escopo disciplinado','Agora, depois e fora de escopo mantêm um fluxo principal completo.'),(13,4,'Integração necessária','IA, experiência visual e automação têm papéis claros no mesmo fluxo.'),
  (14,1,'Valor visível','A interface destaca a tarefa e o resultado, não a tecnologia.'),(14,2,'Base responsiva','O fluxo funciona em 375, 768 e 1440 px.'),(14,3,'Estados completos','Vazio, carregando, sucesso e erro informam ação ou próximo passo.'),(14,4,'Dados mínimos','Modelo, validação, persistência e recuperação sustentam apenas o escopo aprovado.'),
  (15,1,'Fronteiras validadas','Entrada e saída são verificadas antes de IA, dados e efeitos externos.'),(15,2,'Fallback funcional','Falha do modelo principal não encerra o fluxo silenciosamente.'),(15,3,'Automação idempotente','A consequência usa estado ou chave que impede repetição indevida.'),(15,4,'Recuperação observável','Logs e feedback permitem diagnosticar e retomar o fluxo.'),
  (16,1,'Valor ponta a ponta','O deploy entrega a promessa central em um fluxo completo.'),(16,2,'Cinco cenários','A matriz cobre sucesso, inválido, falha da IA, repetição e recuperação.'),(16,3,'Aprendizado externo','O teste com outra pessoa resultou em melhoria identificável.'),(16,4,'Defesa autoral','O aluno explica problema, arquitetura, decisões, limites, evidências e próximos passos.')
)
insert into logos_academy.activity_criteria(
  id, tenant_id, activity_template_id, label, description, position, deleted_at, updated_at
)
select
  md5('logos-academy-explorer-v3-criterion-' || d.activity || '-' || d.position)::uuid,
  t.id,
  md5('logos-academy-explorer-v3-activity-' || d.activity)::uuid,
  d.label,
  d.description,
  d.position,
  null,
  now()
from tenant t cross join data d
on conflict (id) do update set
  label = excluded.label,
  description = excluded.description,
  position = excluded.position,
  deleted_at = null,
  updated_at = now();

commit;
